# Quick lookup: pairs without frequency
VARIANT_PAIRS_ONLY = [(s, t) for s, t, _ in UNIFIED_VARIANT_PAIRS]

def get_top_pairs(n: int) -> list:
    """Get top N variant pairs by frequency."""
    return VARIANT_PAIRS_ONLY[:n]

def get_pairs_above_frequency(min_freq: int) -> list:
    """Get all pairs with frequency >= min_freq."""
    return [(s, t) for s, t, f in UNIFIED_VARIANT_PAIRS if f >= min_freq]